	@Test
	void partialApplicationFailureBeforeFlushAbortsAllSinkMutations() throws Exception {
		try (MemorySailStore store = new MemorySailStore(false);
				SailSource source = store.getExplicitSailSource()) {
			Statement retained = statement("retained");
			Statement abandoned = statement("abandoned-before-failure");
			Statement following = statement("following-after-failure");
			publish(source, retained);

			try (SailDataset oldReader = source.dataset(IsolationLevels.SNAPSHOT_READ)) {
				IllegalStateException failure = new IllegalStateException("approved row iteration failed");
				AtomicInteger consumedRows = new AtomicInteger();
				Set<Statement> approved = new AbstractSet<>() {
					@Override
					public int size() {
						return 2;
					}

					@Override
					public Iterator<Statement> iterator() {
						return new Iterator<>() {
							private int index;

							@Override
							public boolean hasNext() {
								return index < 2;
							}

							@Override
							public Statement next() {
								if (index++ == 0) {
									consumedRows.incrementAndGet();
									return abandoned;
								}
								throw failure;
							}
						};
					}
				};
				try (SailSink aborted = source.sink(IsolationLevels.SNAPSHOT)) {
					aborted.prepare();
					assertSame(failure,
							assertThrows(IllegalStateException.class, () -> aborted.approveAll(approved, Set.of())));
					assertEquals(1, consumedRows.get(), "one real approval was consumed before iteration failed");
				}

				assertCurrentRows(source, Set.of(retained));
				publish(source, following);

				assertRows(oldReader, Set.of(retained));
				assertCurrentRows(source, Set.of(retained, following));
			}
		}
	}

