	@Test
	void abortedExplicitPromotionRestoresTheInferredStatement() throws Exception {
		try (MemorySailStore store = new MemorySailStore(false);
				SailSource inferred = store.getInferredSailSource();
				SailSource explicit = store.getExplicitSailSource()) {
			Statement inferredStatement = statement("inferred-to-explicit-abort");
			publish(inferred, inferredStatement);

			try (SailDataset oldInferred = inferred.dataset(IsolationLevels.SNAPSHOT_READ);
					SailSink abortedPromotion = explicit.sink(IsolationLevels.SNAPSHOT)) {
				abortedPromotion.prepare();
				abortedPromotion.approve(inferredStatement);
				assertRows(oldInferred, Set.of(inferredStatement));
			}

			assertCurrentRows(inferred, Set.of(inferredStatement));
			assertCurrentRows(explicit, Set.of());
			publish(explicit, statement("explicit-followup"));
			assertCurrentRows(inferred, Set.of(inferredStatement));
			assertCurrentRows(explicit, Set.of(statement("explicit-followup")));
		}
	}

	@Test
	void abortedUnpublishedNegativeReadAllowsUnrelatedCommitButNotARealPhantom() throws Exception {
		try (MemorySailStore store = new MemorySailStore(false);
				SailSource source = store.getExplicitSailSource()) {
			Statement observedMissing = statement("serializable-never-published");
			Statement retained = statement("serializable-retained");
			Statement unrelated = statement("serializable-unrelated");
			Statement committedMatch = statement("serializable-committed-phantom");
			publish(source, retained);

			try (SailDataset oldReader = source.dataset(IsolationLevels.SNAPSHOT_READ);
					SailSink observer = source.sink(IsolationLevels.SERIALIZABLE)) {
				observer.observe(observedMissing.getSubject(), observedMissing.getPredicate(),
						observedMissing.getObject());
				try (SailSink aborted = source.sink(IsolationLevels.SNAPSHOT)) {
					aborted.prepare();
					aborted.approve(observedMissing);
				}
				publish(source, unrelated);
				observer.prepare();
				observer.flush();
				assertRows(oldReader, Set.of(retained));
			}

			try (SailSink observer = source.sink(IsolationLevels.SERIALIZABLE)) {
				observer.observe(committedMatch.getSubject(), committedMatch.getPredicate(),
						committedMatch.getObject());
				publish(source, committedMatch);
				assertThrows(SailConflictException.class, observer::prepare,
						"a real committed matching row remains a SERIALIZABLE phantom conflict");
			}
			assertCurrentRows(source, Set.of(retained, unrelated, committedMatch));
		}
	}

